'use strict';

// Focused qualification for three exact fallback-runtime changes. The control
// is generated by reversing only these edits from the current source, so both
// modules share every other v1.13 optimization and dependency.

const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { performance } = require('node:perf_hooks');
const { spawnSync } = require('node:child_process');
const ts = require('typescript');

const ROOT = path.resolve(__dirname, '..');
const SOURCE = path.join(ROOT, 'src/physics/fallback.ts');
const SAMPLE_COUNT = Math.max(8, Number.parseInt(process.env.FALLBACK_LOW_RISK_SAMPLES || '12', 10));
const RESULTS_JSON = path.join(ROOT, 'benchmarks/results/v113-fallback-low-risk.json');
const RESULTS_MD = path.join(ROOT, 'benchmarks/results/v113-fallback-low-risk.md');
let observableSink = 0;

function replaceOnce(source, from, to, label) {
  const first = source.indexOf(from);
  assert.notEqual(first, -1, `missing ${label} candidate marker`);
  assert.equal(source.indexOf(from, first + from.length), -1, `ambiguous ${label} candidate marker`);
  return source.slice(0, first) + to + source.slice(first + from.length);
}

function makeExactPreEditControl(candidateSource) {
  let source = candidateSource;
  source = replaceOnce(source, '  private dynamicBodyCount = 0;\n', '', 'dynamic-count field');
  source = replaceOnce(
    source,
    '  dynamicCount(): number { return this.dynamicBodyCount; }',
    '  dynamicCount(): number { return this.bodies.reduce((sum, body) => sum + (body.dynamic ? 1 : 0), 0); }',
    'dynamic-count query',
  );
  source = replaceOnce(
    source,
    `  destroy(): void {\n    this.resetSceneState();\n    // Public destruction keeps the historical observable zeroed-heap contract.\n    // Scene replacement uses resetForScene() because every active slot is\n    // overwritten by addBox() before the new body count is exposed.\n    this.HEAPF32.fill(0);\n  }\n\n  private resetSceneState(): void {\n    this.bodies.length = 0;\n    this.dynamicBodyCount = 0;\n    this.hashValue = 0;\n    this.hashDirty = false;\n    this.broadphaseCount = 0;\n    this.broadphaseCandidateCountValue = 0;\n  }\n\n  private resetForScene(): void {\n    this.resetSceneState();\n  }`,
    `  destroy(): void {\n    this.bodies.length = 0;\n    this.HEAPF32.fill(0);\n    this.hashValue = 0;\n    this.hashDirty = false;\n    this.broadphaseCount = 0;\n    this.broadphaseCandidateCountValue = 0;\n  }`,
    'scene-reset implementation',
  );
  source = replaceOnce(source, '    this.resetForScene();', '    this.destroy();', 'create-scene reset call');
  source = replaceOnce(
    source,
    `    // Cloth and rope recipes use the rigid backend only for immutable stage\n    // geometry. With no dynamic bodies there is no integration, collision,\n    // heat decay, transform reconstruction, or stream revision to publish.\n    if (this.dynamicBodyCount === 0) return;\n`,
    '',
    'static-only step guard',
  );
  source = replaceOnce(source, '    if (body.dynamic) this.dynamicBodyCount++;\n', '', 'dynamic-count increment');
  return source;
}

function compileProjects(tempRoot, candidateSource, controlSource) {
  const candidateBuild = path.join(tempRoot, 'candidate');
  const controlBuild = path.join(tempRoot, 'control');
  const tsc = path.join(ROOT, 'node_modules/.bin/tsc');
  const result = spawnSync(tsc, ['-p', path.join(ROOT, 'tsconfig.test.json'), '--outDir', candidateBuild], {
    cwd: ROOT,
    encoding: 'utf8',
  });
  if (result.status !== 0) throw new Error(result.stdout + result.stderr);
  fs.cpSync(candidateBuild, controlBuild, { recursive: true });
  const transpiled = ts.transpileModule(controlSource, {
    compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.CommonJS },
    fileName: SOURCE,
  }).outputText;
  fs.writeFileSync(path.join(controlBuild, 'src/physics/fallback.js'), transpiled);
  fs.writeFileSync(path.join(candidateBuild, 'package.json'), '{"type":"commonjs"}\n');
  fs.writeFileSync(path.join(controlBuild, 'package.json'), '{"type":"commonjs"}\n');

  function load(buildRoot, label) {
    return {
      label,
      SCENES: require(path.join(buildRoot, 'src/scenes.js')).SCENES,
      FallbackPhysicsBackend: require(path.join(buildRoot, 'src/physics/fallback.js')).FallbackPhysicsBackend,
    };
  }
  return {
    candidate: load(candidateBuild, 'candidate'),
    control: load(controlBuild, 'exact pre-edit control'),
  };
}

function median(values) {
  const sorted = [...values].sort((a, b) => a - b);
  const middle = sorted.length >> 1;
  return sorted.length & 1 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) * 0.5;
}

function mad(values) {
  const center = median(values);
  return median(values.map((value) => Math.abs(value - center)));
}

function timeBatch(operation, iterations) {
  const start = performance.now();
  for (let iteration = 0; iteration < iterations; iteration++) {
    observableSink = (observableSink + operation(iteration)) >>> 0;
  }
  return ((performance.now() - start) * 1e6) / iterations;
}

function runTimedCase(projects, definition) {
  const controlState = definition.setup(projects.control);
  const candidateState = definition.setup(projects.candidate);
  const controlIterations = definition.controlIterations ?? definition.iterations;
  const candidateIterations = definition.candidateIterations ?? definition.iterations;
  for (let warmup = 0; warmup < 3; warmup++) {
    timeBatch(() => definition.operation(controlState), Math.max(1, Math.floor(controlIterations / 5)));
    timeBatch(() => definition.operation(candidateState), Math.max(1, Math.floor(candidateIterations / 5)));
  }
  const control = [];
  const candidate = [];
  for (let sample = 0; sample < SAMPLE_COUNT; sample++) {
    if (global.gc) global.gc();
    if ((sample & 1) === 0) {
      control.push(timeBatch(() => definition.operation(controlState), controlIterations));
      candidate.push(timeBatch(() => definition.operation(candidateState), candidateIterations));
    } else {
      candidate.push(timeBatch(() => definition.operation(candidateState), candidateIterations));
      control.push(timeBatch(() => definition.operation(controlState), controlIterations));
    }
  }
  const controlNs = median(control);
  const candidateNs = median(candidate);
  return {
    id: definition.id,
    controlIterations,
    candidateIterations,
    controlNsPerOperation: controlNs,
    candidateNsPerOperation: candidateNs,
    speedup: controlNs / candidateNs,
    controlNormalizedMad: mad(control) / controlNs,
    candidateNormalizedMad: mad(candidate) / candidateNs,
    controlSamples: control,
    candidateSamples: candidate,
  };
}

function activeFingerprint(backend) {
  const count = backend.bodyCount();
  const matrixStart = Number(backend._b3w_matrices_ptr()) / 4;
  const colorStart = Number(backend._b3w_colors_ptr()) / 4;
  const hash = crypto.createHash('sha256');
  hash.update(Buffer.from(backend.HEAPF32.buffer, (matrixStart * 4), count * 16 * 4));
  hash.update(Buffer.from(backend.HEAPF32.buffer, (colorStart * 4), count * 4 * 4));
  return {
    count,
    dynamicCount: backend.dynamicCount(),
    replayHash: backend.replayHash() >>> 0,
    streamSha256: hash.digest('hex'),
  };
}

function exactnessChecks(projects) {
  const checks = [];
  for (const sceneId of [39, 600, 620, 650, 670]) {
    const control = new projects.control.FallbackPhysicsBackend(4096);
    const candidate = new projects.candidate.FallbackPhysicsBackend(4096);
    control.createScene(projects.control.SCENES[sceneId], 5, 0x710000 + sceneId);
    candidate.createScene(projects.candidate.SCENES[sceneId], 5, 0x710000 + sceneId);
    assert.deepEqual(activeFingerprint(candidate), activeFingerprint(control), `creation output changed for scene ${sceneId}`);
    const before = activeFingerprint(candidate);
    if (sceneId >= 600) {
      for (let frame = 0; frame < 240; frame++) {
        control.step(1 / 60, 4);
        candidate.step(1 / 60, 4);
      }
      assert.deepEqual(activeFingerprint(candidate), activeFingerprint(control), `static-step output changed for scene ${sceneId}`);
      assert.deepEqual(activeFingerprint(candidate), before, `static candidate state changed for scene ${sceneId}`);
      assert.equal(candidate.frameVersion(), 1, 'candidate should retain its creation transform revision');
      assert.equal(candidate.colorVersion(), 1, 'candidate should retain its creation color revision');
      assert.equal(control.frameVersion(), 241, 'control should demonstrate the redundant historical revisions');
      assert.equal(control.colorVersion(), 241, 'control should demonstrate the redundant historical color revisions');
    }
    checks.push({ sceneId, activeExact: true });
  }

  const control = new projects.control.FallbackPhysicsBackend(4096);
  const candidate = new projects.candidate.FallbackPhysicsBackend(4096);
  for (const sceneId of [39, 600, 39]) {
    control.createScene(projects.control.SCENES[sceneId], 5, 0x720000 + sceneId);
    candidate.createScene(projects.candidate.SCENES[sceneId], 5, 0x720000 + sceneId);
    assert.deepEqual(activeFingerprint(candidate), activeFingerprint(control), `reset sequence changed scene ${sceneId}`);
  }
  candidate.destroy();
  assert.equal(candidate.bodyCount(), 0);
  assert.equal(candidate.dynamicCount(), 0);
  assert.ok(candidate.HEAPF32.every((value) => value === 0), 'public destroy stopped clearing the heap');
  checks.push({ sequence: [39, 600, 39], activeExact: true, publicDestroyZeroed: true });
  return checks;
}

function main() {
  assert.equal(SAMPLE_COUNT % 2, 0, 'FALLBACK_LOW_RISK_SAMPLES must be even');
  const candidateSource = fs.readFileSync(SOURCE, 'utf8');
  const controlSource = makeExactPreEditControl(candidateSource);
  const tempRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'box3d-fallback-low-risk-'));
  try {
    const projects = compileProjects(tempRoot, candidateSource, controlSource);
    const exactness = exactnessChecks(projects);
    const definitions = [
      {
        id: 'cached-dynamic-count-3410', controlIterations: 5000, candidateIterations: 2000000,
        setup: (project) => {
          const backend = new project.FallbackPhysicsBackend(4096);
          backend.createScene(project.SCENES[39], 5, 0x730039);
          assert.equal(backend.dynamicCount(), 3410);
          return backend;
        },
        operation: (backend) => backend.dynamicCount(),
      },
      {
        id: 'static-cloth-rigid-step', controlIterations: 50000, candidateIterations: 3000000,
        setup: (project) => {
          const backend = new project.FallbackPhysicsBackend(4096);
          backend.createScene(project.SCENES[600], 5, 0x730600);
          assert.equal(backend.dynamicCount(), 0);
          return backend;
        },
        operation: (backend) => { backend.step(1 / 60, 4); return backend.bodyCount(); },
      },
      {
        id: 'static-rope-rigid-step', controlIterations: 50000, candidateIterations: 3000000,
        setup: (project) => {
          const backend = new project.FallbackPhysicsBackend(4096);
          backend.createScene(project.SCENES[650], 5, 0x730650);
          assert.equal(backend.dynamicCount(), 0);
          return backend;
        },
        operation: (backend) => { backend.step(1 / 60, 4); return backend.bodyCount(); },
      },
      {
        id: 'repeated-small-scene-create', iterations: 5000,
        setup: (project) => new project.FallbackPhysicsBackend(4096),
        operation: (backend) => backend.createScene(projects.candidate.SCENES[600], 5, 0x730600),
      },
      {
        id: 'repeated-large-scene-create', iterations: 100,
        setup: (project) => new project.FallbackPhysicsBackend(4096),
        operation: (backend) => backend.createScene(projects.candidate.SCENES[39], 5, 0x730039),
      },
      {
        id: 'complete-dynamic-frame-control', iterations: 1000,
        setup: (project) => {
          const backend = new project.FallbackPhysicsBackend(4096);
          backend.createScene(project.SCENES[390], 5, 0x730390);
          assert.equal(backend.bodyCount(), 135);
          assert.equal(backend.dynamicCount(), 38);
          return backend;
        },
        operation: (backend) => { backend.step(1 / 60, 2); return backend.bodyCount(); },
      },
    ];
    const records = definitions.map((definition) => runTimedCase(projects, definition));
    const result = {
      schemaVersion: 1,
      generatedAt: new Date().toISOString(),
      node: process.version,
      platform: `${process.platform}/${process.arch}`,
      samples: SAMPLE_COUNT,
      candidateSourceSha256: crypto.createHash('sha256').update(candidateSource).digest('hex'),
      controlSourceSha256: crypto.createHash('sha256').update(controlSource).digest('hex'),
      control: 'exact current-source pre-edit reconstruction; only the three scoped edits are reversed',
      exactness,
      records,
      observableSink,
    };
    fs.mkdirSync(path.dirname(RESULTS_JSON), { recursive: true });
    fs.writeFileSync(RESULTS_JSON, `${JSON.stringify(result, null, 2)}\n`);
    const lines = [
      '# v1.13 fallback low-risk qualification', '',
      `- Samples: ${SAMPLE_COUNT} (alternating order)`,
      '- Control: exact current-source pre-edit reconstruction',
      '- Active stream, count, and replay-hash exactness: passed',
      '- Public destroy zeroed-heap contract: passed', '',
      '| Case | Control ns/op | Candidate ns/op | Speedup | Control MAD | Candidate MAD |',
      '|---|---:|---:|---:|---:|---:|',
      ...records.map((record) => `| ${record.id} | ${record.controlNsPerOperation.toFixed(2)} | ${record.candidateNsPerOperation.toFixed(2)} | **${record.speedup.toFixed(3)}×** | ${(record.controlNormalizedMad * 100).toFixed(2)}% | ${(record.candidateNormalizedMad * 100).toFixed(2)}% |`),
      '',
      'The static-step ratios measure exact rigid-backend work elimination while cloth/rope simulation remains in the separate soft-system layer. Query speed is not a whole-frame claim.',
    ];
    fs.writeFileSync(RESULTS_MD, `${lines.join('\n')}\n`);
    console.log(lines.join('\n'));
  } finally {
    fs.rmSync(tempRoot, { recursive: true, force: true });
  }
}

main();
